// Render a published page: the pre-built self-contained viewer template with
// the project document embedded as JSON. The template is generated by
// `npm run build:viewer` (scripts/build-viewer.mjs) and inlined into this
// Lambda's bundle at synth time (esbuild text loader).
import viewerTemplate from "../generated/viewer.html";

function escapeHtml(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

export function renderPublishedPage(title: string, project: unknown): string {
  // <-escape so "</script>" inside code strings can't break out of the
  // embedded JSON block; it remains valid JSON.
  const json = JSON.stringify(project).replace(/</g, "\\u003c");
  return viewerTemplate
    .replaceAll("{{TITLE}}", escapeHtml(title))
    .replace("{{PROJECT_JSON}}", () => json);
}
